import { createElement } from "react";
import { render } from "react-email";

import { TransactionalEmail } from "./transactional-email";

export { TransactionalEmail } from "./transactional-email";

export interface MailingTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  primary: string;
  primaryForeground: string;
  muted: string;
  mutedForeground: string;
  border: string;
  fontSans: string;
  fontSerif: string;
}

export interface MailingBrand {
  name: string;
  logoUrl?: string;
  /** Concrete email-safe values for the host's semantic roles, not CSS variables. */
  theme?: Partial<MailingTheme>;
}

export interface EmailContent {
  locale?: string;
  preview: string;
  heading: string;
  greeting?: string;
  paragraphs: string[];
  details?: { label: string; value: string }[];
  action?: { label: string; url: string };
  footer?: string;
}

export interface RenderedEmail {
  html: string;
  text: string;
}

/** React Email renders HTML; the text alternative preserves the host's copy and labels. */
export async function renderEmail(
  content: EmailContent & { brand: MailingBrand },
): Promise<RenderedEmail> {
  const html = await render(createElement(TransactionalEmail, content));
  const { brand } = content;
  const text = [
    brand.name,
    content.heading,
    content.greeting,
    ...content.paragraphs,
    content.details?.map(({ label, value }) => `${label}: ${value}`).join("\n"),
    content.action && `${content.action.label}\n${content.action.url}`,
    content.footer,
  ]
    .filter(Boolean)
    .join("\n\n");
  return { html, text };
}

import { Fragment } from "react";
import {
  Body,
  Button,
  Container,
  Head,
  Heading,
  Html,
  Img,
  Link,
  Preview,
  Section,
  Text,
} from "react-email";

import type { EmailContent, MailingBrand, MailingTheme } from "./index";

const defaultTheme: MailingTheme = {
  background: "#f4f7f7",
  foreground: "#13343a",
  card: "#ffffff",
  cardForeground: "#13343a",
  primary: "#13343a",
  primaryForeground: "#ffffff",
  muted: "#edf4f4",
  mutedForeground: "#486266",
  border: "#dbe5e5",
  fontSans: "Arial, Helvetica, sans-serif",
  fontSerif: "Georgia, 'Times New Roman', serif",
};

function httpUrl(value: string) {
  const url = new URL(value);
  if (!["https:", "http:"].includes(url.protocol) || url.username || url.password)
    throw new Error("Email links and images require an absolute HTTP(S) URL without credentials.");
  return value;
}

export function TransactionalEmail({ brand, ...content }: EmailContent & { brand: MailingBrand }) {
  const theme = { ...defaultTheme, ...brand.theme };
  const actionUrl = content.action ? httpUrl(content.action.url) : undefined;
  const logoUrl = brand.logoUrl ? httpUrl(brand.logoUrl) : undefined;
  const paragraphStyle = { margin: "0 0 20px", fontSize: "16px", lineHeight: "26px" };
  return (
    <Html lang={content.locale ?? "en"}>
      <Head>
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta name="color-scheme" content="light" />
        <title>{content.heading}</title>
      </Head>
      <Body
        lang={content.locale ?? "en"}
        style={{
          margin: 0,
          padding: "32px 12px",
          backgroundColor: theme.background,
          color: theme.foreground,
          fontFamily: theme.fontSans,
        }}
      >
        <Preview useTitleTag={false}>{content.preview}</Preview>
        <Container
          style={{
            maxWidth: "520px",
            backgroundColor: theme.card,
            color: theme.cardForeground,
            border: `1px solid ${theme.border}`,
            borderRadius: "12px",
          }}
        >
          <Section
            style={{ padding: "32px 24px", overflowWrap: "anywhere", wordBreak: "break-word" }}
          >
            <Section style={{ textAlign: "center", marginBottom: "32px" }}>
              {logoUrl && (
                <Img
                  src={logoUrl}
                  alt=""
                  width="64"
                  height="64"
                  style={{
                    display: "block",
                    margin: "0 auto 16px",
                    border: 0,
                    objectFit: "contain",
                  }}
                />
              )}
              <Text style={{ margin: 0, fontSize: "16px", fontWeight: 600 }}>{brand.name}</Text>
            </Section>
            <Heading
              as="h1"
              style={{
                margin: "0 0 28px",
                fontFamily: theme.fontSerif,
                fontSize: "28px",
                lineHeight: "36px",
                fontWeight: 600,
                textAlign: "center",
              }}
            >
              {content.heading}
            </Heading>
            {[...(content.greeting ? [content.greeting] : []), ...content.paragraphs].map(
              (paragraph, index) => (
                <Text key={index} style={paragraphStyle}>
                  {paragraph.split("\n").map((line, lineIndex) => (
                    <Fragment key={lineIndex}>
                      {lineIndex > 0 && <br />}
                      {line}
                    </Fragment>
                  ))}
                </Text>
              ),
            )}
            {!!content.details?.length && (
              <Section
                style={{
                  margin: "8px 0 28px",
                  padding: "20px",
                  backgroundColor: theme.muted,
                  borderRadius: "8px",
                }}
              >
                <table width="100%" cellPadding="0" cellSpacing="0">
                  <tbody>
                    {content.details.map(({ label, value }, index) => (
                      <tr key={index}>
                        <th
                          scope="row"
                          align="left"
                          style={{
                            padding: "6px 16px 6px 0",
                            verticalAlign: "top",
                            fontSize: "14px",
                            lineHeight: "22px",
                            fontWeight: 400,
                            color: theme.mutedForeground,
                          }}
                        >
                          {label}
                        </th>
                        <td
                          align="right"
                          style={{
                            padding: "6px 0",
                            verticalAlign: "top",
                            fontSize: "14px",
                            lineHeight: "22px",
                            fontWeight: 600,
                          }}
                        >
                          {value}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </Section>
            )}
            {content.action && (
              <>
                <Section style={{ textAlign: "center", margin: "4px 0 24px" }}>
                  <Button
                    href={actionUrl}
                    style={{
                      padding: "14px 24px",
                      backgroundColor: theme.primary,
                      color: theme.primaryForeground,
                      fontSize: "16px",
                      lineHeight: "24px",
                      fontWeight: 600,
                      textDecoration: "none",
                      borderRadius: "6px",
                    }}
                  >
                    {content.action.label}
                  </Button>
                </Section>
                <Text
                  style={{
                    margin: "0 0 24px",
                    fontSize: "12px",
                    lineHeight: "20px",
                    wordBreak: "break-all",
                  }}
                >
                  <Link
                    href={actionUrl}
                    style={{ color: theme.mutedForeground, textDecoration: "underline" }}
                  >
                    {content.action.url}
                  </Link>
                </Text>
              </>
            )}
            {content.footer && (
              <Text
                style={{
                  margin: "28px 0 0",
                  paddingTop: "20px",
                  borderTop: `1px solid ${theme.border}`,
                  color: theme.mutedForeground,
                  fontSize: "12px",
                  lineHeight: "20px",
                }}
              >
                {content.footer}
              </Text>
            )}
          </Section>
        </Container>
      </Body>
    </Html>
  );
}

export interface OutgoingEmail {
  to: string;
  subject: string;
  text: string;
  html?: string;
  /** Stable notification ID; reuse it on retries. */
  id?: string;
}

/** Server-only transport. The host supplies credentials and owns delivery/retry policy. */
export async function sendResendEmail(
  config: { apiKey: string | undefined; from: string | undefined },
  email: OutgoingEmail,
): Promise<void> {
  if (!config.apiKey || !config.from) throw new Error("Email delivery is not configured.");
  const response = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      "Content-Type": "application/json",
      ...(email.id ? { "Idempotency-Key": email.id } : {}),
    },
    body: JSON.stringify({
      from: config.from,
      to: [email.to],
      subject: email.subject,
      text: email.text,
      html: email.html,
    }),
    signal: AbortSignal.timeout(10_000),
  });
  if (!response.ok) throw new Error("Email delivery failed.");
}
